mapper.select:
SELECT
    target_round_count
FROM mission_daily_goal
WHERE trip_id = #{tripId}
  AND day_no = #{dayNo}

SELECT
    COUNT(*)
FROM trip_mission
WHERE trip_id = #{tripId}
  AND day_no = #{dayNo}
  AND status IN ('COMPLETED', 'FAILED', 'NOT_PERFORMED')

SELECT
    picker_member_id
FROM mission_candidate
WHERE trip_id = #{tripId}
  AND day_no = #{dayNo}
  AND assigned_order = #{assignedOrder}
LIMIT 1

SELECT m.mission_id FROM mission m LEFT JOIN mission_candidate mc ON mc.mission_id = m.mission_id AND mc.trip_id = #{tripId} AND mc.selected_yn = 'Y'
AND m.use_yn = 'Y' AND m.region_id = #{tripRegionId} AND mc.mission_candidate_id IS NULL
ORDER BY RAND() LIMIT #{cnt}

SELECT
    COUNT(*)
FROM trip_mission
WHERE trip_id = #{tripId}
  AND trip_mission_id = #{tripMissionId}
  AND status = 'IN_PROGRESS'

SELECT
    COUNT(*)
FROM member_rel_trip
WHERE trip_id = #{tripId}
  AND member_id = #{memberId}
  AND status = 'JOINED'

SELECT
    COUNT(*)
FROM trip_mission
WHERE trip_id = #{tripId}
  AND day_no = #{dayNo}
